            while i >= 0 and digits[i] >= digits[i + 1]:
                i -= 1
            j = n - 1
            while digits[j] <= digits[i]:
                j -= 1
            digits[i], digits[j] = digits[j], digits[i]
            digits[i + 1:] = digits[i + 1:][::-1]
        cur = list(num)
        res = 0
        for i in range(n):
            if cur[i] == digits[i]:
                continue
            j = i + 1
            while cur[j] != digits[i]:
                j += 1
            while j > i:
                cur[j], cur[j - 1] = cur[j - 1], cur[j]
                res += 1
                j -= 1
        return res

