class Solution {
public:
    int getMinSwaps(string num, int k) {
        int n = num.size();
        vector<int> d(num.begin(), num.end());
        for (int t = 0; t < k; ++t) {
            int i = n - 2;
            while (i >= 0 && d[i] >= d[i + 1]) --i;
            int j = n - 1;
            while (d[j] <= d[i]) --j;
            swap(d[i], d[j]);
            reverse(d.begin() + i + 1, d.end());
        }
        vector<int> cur(num.begin(), num.end());
        int res = 0;
        for (int i = 0; i < n; ++i) {
            if (cur[i] == d[i]) continue;
            int j = i + 1;
            while (cur[j] != d[i]) ++j;
            while (j > i) { swap(cur[j], cur[j - 1]); ++res; --j; }
        }
        return res;
    }
};

