class Solution {
    public int getMinSwaps(String num, int k) {
        char[] d = num.toCharArray();
        int n = d.length;
        for (int t = 0; t < k; t++) {
            int i = n - 2;
            while (i >= 0 && d[i] >= d[i + 1]) i--;
            int j = n - 1;
            while (d[j] <= d[i]) j--;
            char tmp = d[i]; d[i] = d[j]; d[j] = tmp;
            for (int l = i + 1, r = n - 1; l < r; l++, r--) {
                tmp = d[l]; d[l] = d[r]; d[r] = tmp;
            }
        }
        char[] cur = num.toCharArray();
        int res = 0;
        for (int i = 0; i < n; i++) {
            if (cur[i] == d[i]) continue;
            int j = i + 1;
            while (cur[j] != d[i]) j++;
            while (j > i) {
                char tmp = cur[j]; cur[j] = cur[j - 1]; cur[j - 1] = tmp;
                res++; j--;
            }
        }
        return res;
    }
}

