class Solution:
    def getMinSwaps(self, num: str, k: int) -> int:
        digits = list(map(int, num))
        n = len(digits)
        for _ in range(k):
            i = n - 2
            while i >= 0 and digits[i] >= digits[i + 1]:
                i -= 1
            j = n - 1
            while digits[j] <= digits[i]:
                j -= 1
            digits[i], digits[j] = digits[j], digits[i]
            digits[i + 1:] = digits[i + 1:][::-1]
        pos = [[] for _ in range(10)]
        for i, c in enumerate(num):
            pos[int(c)].append(i)
        ptr = [0] * 10
        tree = [0] * (n + 1)

        def update(x, v):
            x += 1
            while x <= n:
                tree[x] += v
                x += x & (-x)

        def query(x):
            s = 0
            x += 1
            while x > 0:
                s += tree[x]
                x -= x & (-x)
            return s

        for i in range(n):
            update(i, 1)
        res = 0
        for dg in digits:
            p = pos[dg][ptr[dg]]
            ptr[dg] += 1
            res += query(p - 1)
            update(p, -1)
        return res

