class Solution {
    private int[] tree;

    public int getMinSwaps(String num, int k) {
        char[] d = num.toCharArray();
        int n = d.length;
        for (int t = 0; t < k; t++) {
            int i = n - 2;
            while (i >= 0 && d[i] >= d[i + 1]) i--;
            int j = n - 1;
            while (d[j] <= d[i]) j--;
            char tmp = d[i]; d[i] = d[j]; d[j] = tmp;
            for (int l = i + 1, r = n - 1; l < r; l++, r--) {
                tmp = d[l]; d[l] = d[r]; d[r] = tmp;
            }
        }
        List<Integer>[] pos = new List[10];
        for (int i = 0; i < 10; i++) pos[i] = new ArrayList<>();
        for (int i = 0; i < n; i++) pos[d[i] - '0'].add(i);
        int[] ptr = new int[10];
        tree = new int[n + 1];
        for (int i = 0; i < n; i++) upd(i, 1);
        int res = 0;
        for (char c : d) {
            int dg = c - '0';
            int p = pos[dg].get(ptr[dg]++);
            res += qry(p - 1);
            upd(p, -1);
        }
        return res;
    }

    private void upd(int x, int v) {
        for (++x; x < tree.length; x += x & (-x)) tree[x] += v;
    }

    private int qry(int x) {
        int s = 0;
        for (++x; x > 0; x -= x & (-x)) s += tree[x];
        return s;
    }
}

